// --- 1. Events ---
abstract class CounterEvent {}

class CounterIncrementPressed extends CounterEvent {}

// --- 2. States ---
abstract class CounterState {
  final int count;
  const CounterState(this.count);
}

class CounterInitial extends CounterState {
  const CounterInitial() : super(0);
}

class CounterLoaded extends CounterState {
  const CounterLoaded(super.count);

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is CounterLoaded && runtimeType == other.runtimeType && count == other.count;

  @override
  int get hashCode => count.hashCode;
}

import 'package:bloc/bloc.dart';
// (Step 2의 State 및 Event 정의 코드 생략)

class CounterBloc extends Bloc<CounterEvent, CounterState> {
  // 초기 상태는 CounterInitial(0)로 설정
  CounterBloc() : super(const CounterInitial()) {
    // CounterIncrementPressed 이벤트가 들어오면 _onIncrement 호출
    on<CounterIncrementPressed>(_onIncrement);
  }

  void _onIncrement(
    CounterIncrementPressed event,
    Emitter<CounterState> emit,
  ) {
    // 현재 상태의 count 값을 가져와 1 증가
    final newCount = state.count + 1;

    // 새로운 상태(CounterLoaded)를 방출(emit)
    emit(CounterLoaded(newCount));
  }
}

import 'package:bloc/bloc.dart';
import 'package:flutter/material.dart';
import 'package:flutter_bloc_guide/counter/counter_bloc.dart';
import 'package:flutter_bloc_guide/counter/counter_page.dart';

// 공식 예제 기반의 Observer 구현
class SimpleBlocObserver extends BlocObserver {
  const SimpleBlocObserver();

  @override
  void onChange(BlocBase<dynamic> bloc, Change<dynamic> change) {
    super.onChange(bloc, change);
    // 실무에서는 Logger 패키지를 사용하여 깔끔하게 출력합니다.
    debugPrint('onChange -- bloc: ${bloc.runtimeType}, change: $change');
  }

  @override
  void onError(BlocBase<dynamic> bloc, Object error, StackTrace stackTrace) {
    debugPrint('onError -- bloc: ${bloc.runtimeType}, error: $error');
    super.onError(bloc, error, stackTrace);
  }
  // onCreate, onEvent, onClose 등 다른 메서드 생략...
}

void main() {
  // BLoC 관찰자 등록
  Bloc.observer = const SimpleBlocObserver();
  runApp(const MyApp());
}

class MyApp extends StatelessWidget {
  const MyApp({super.key});

  @override
  Widget build(BuildContext context) {
    return const MaterialApp(
      home: CounterPage(),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:flutter_bloc/flutter_bloc.dart';
import 'package:flutter_bloc_guide/counter/counter_bloc.dart';

class CounterPage extends StatelessWidget {
  const CounterPage({super.key});

  @override
  Widget build(BuildContext context) {
    // 1. BlocProvider: BLoC 인스턴스를 생성하고 위젯 트리에 제공
    return BlocProvider(
      create: (context) => CounterBloc(),
      child: const CounterView(),
    );
  }
}

class CounterView extends StatelessWidget {
  const CounterView({super.key});

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('BLoC Counter')), 
      body: Center(
        // 2. BlocBuilder: CounterBloc의 상태 변화를 감지하여 UI 업데이트
        child: BlocBuilder<CounterBloc, CounterState>(
          builder: (context, state) {
            // 상태에 따라 다른 UI를 보여줄 수 있음 (예: 로딩 중)
            return Text(
              'Count: ${state.count}',
              style: Theme.of(context).textTheme.headlineLarge,
            );
          },
        ),
      ),
      floatingActionButton: FloatingActionButton(
        onPressed: () {
          // 3. Event Dispatch: BLoC 인스턴스를 읽어 이벤트 추가
          context.read<CounterBloc>().add(CounterIncrementPressed());
        },
        tooltip: 'Increment',
        child: const Icon(Icons.add),
      ),
    );
  }
}
